"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4738],{68155:e=>{e.exports=JSON.parse('{"functions":[{"name":"SortOrder","desc":"","params":[{"name":"item","desc":"","lua_type":"ItemInstance"}],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"method","source":{"line":58,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/Behaviour.luau"}}],"properties":[],"types":[],"name":"Behaviour","desc":"Category behaviour, dispatched on the ItemType discriminant.\\n\\nThis is what replaces the ConstructorItems inheritance chain. Where\\nAmmoItem overrode `SortOrder` and called up to `BaseItem.SortOrder(self)`,\\nthere is now a plain default plus a per-category override in a lookup table.\\n\\nThe win over `:Extend()` is that the compiler can see it: inside the \'Ammo\'\\narm, `config.AmmoType` is known to exist and to be an AmmoType. Under the\\nold model `self` was `any`, so a typo\'d or missing field was silent.","source":{"line":16,"path":"src2/shared/EmberSharedLibrary/GameShared/Item2/Behaviour.luau"}}')}}]);